ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload ++ {
  details: {
    errorType: vars.logError.errorType.identifier default null,
    description: vars.logError.description default null,
    detailedDescription: vars.logError.detailedDescription default null
  }
}

set-variable.value:
#[{
        httpStatus: 422,
        code: "PAYMENT_VALIDATION_FAILED",
        message: "Invalid payment details"
    }]

#[{
  httpStatus: 409,
  code: "IDEMPOTENCY_PAYLOAD_CONFLICT",
  message: "The idempotency key was reused with a different request payload"
}]

#[%dw 2.0
output application/java

var errorText =
    lower(
        (error.description default '')
        ++ ' '
        ++
        (error.detailedDescription default '')
    )

---
if (errorText contains 'api_idempotency')
{
    httpStatus: 409,
    code: 'REQUEST_IN_PROGRESS',
    message: 'A request with this idempotency key is already being processed'
}
else
{
    httpStatus: 409,
    code: 'DUPLICATE_ORDER',
    message: 'An order with this externalOrderId already exists'
}]
